import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges, ViewChild, ElementRef, AfterViewChecked } from '@angular/core';
import { ConversationData, ConversationItem, isSystemMessage } from '@/app/core/models';
import { MessagesService } from '@/app/core/services/messages.service';
import { highlightText } from '@/app/core/utils/search.utils';

@Component({
    selector: 'app-conversation-detail',
    template: `
    <div *ngIf="!messageId" class="flex-1 flex flex-col items-center justify-center bg-white text-[#666] gap-4">
      <!-- Empty State SVG -->
      <svg xmlns="http://www.w3.org/2000/svg" width="110" height="83" viewBox="0 0 110 83" fill="none">
         <path d="M80.5241 72.173H30.3591C28.5223 72.1727 26.7608 71.4429 25.462 70.1441C24.1632 68.8453 23.4334 67.0838 23.4331 65.247V14.811H102.866C104.703 14.811 106.465 15.5406 107.764 16.8395C109.063 18.1383 109.793 19.9 109.793 21.737V72.173H96.6831V82.303L80.5241 72.173Z" fill="#E5E5E5"/>
         <path d="M13.111 57.358H6.846C5.03024 57.3577 3.28893 56.6362 2.00509 55.3522C0.721241 54.0682 -1.93655e-08 52.3268 0 50.511L0 0H79.517C81.3328 -1.93655e-08 83.0742 0.721241 84.3582 2.00509C85.6422 3.28893 86.3637 5.03024 86.364 6.846V57.358H29.278L13.111 67.493V57.358Z" fill="#CCCCCC"/>
      </svg>
      <p class="text-lg">Select a conversation to view messages</p>
    </div>

    <div *ngIf="messageId && conversation" class="flex-1 bg-white flex flex-col min-w-0 h-full">
      <!-- Top Header -->
      <div class="border-b border-[#e6e6e6] px-6 py-4 flex items-center justify-between">
        <div class="flex-1 min-w-0 pr-4">
           <h2 class="text-xl font-bold text-[#262626] truncate" [title]="conversation.title">
             {{ conversation.title }}
           </h2>
        </div>
        <div class="flex items-center gap-4">
           <span class="text-sm text-[#666]">Updated: {{ conversation.lastUpdated }}</span>
           
           <div class="flex items-center gap-1 px-4 py-1.5 border border-[#262626] bg-[#f5f5f5] rounded-[4px]">
              <app-icon name="participants" size="15"></app-icon>
              <span class="text-sm font-bold text-[#262626]">{{ (conversation.participantsList || []).length }}</span>
           </div>
        </div>
      </div>

      <!-- Messages Thread -->
      <div class="flex-1 overflow-y-auto message-list-scrollbar p-6 bg-[#fbfbfb]">
         <div class="flex flex-col gap-3 min-h-full justify-end">
            <ng-container *ngFor="let item of conversation.messages">
                
                <!-- System Message -->
                <div *ngIf="isSystem(item)" class="flex justify-center my-2">
                    <span class="bg-[#f0f0f0] text-[#666] text-xs px-2 py-1 rounded">
                       {{ getSystemMessageText(item) }} - {{ item.timestamp }}
                    </span>
                </div>

                <!-- Chat Message -->
                <div *ngIf="!isSystem(item)" 
                     class="flex w-full group relative"
                     [ngClass]="getIsOwn(item) ? 'justify-end' : 'justify-start'"
                >
                    <div class="max-w-[70%] border rounded-lg p-4 bg-white shadow-sm border-[#e6e6e6]">
                        <div class="flex items-start justify-between gap-6 mb-3">
                            <span class="font-bold text-[#007a91]">
                                <span [innerHTML]="highlight(getSender(item))"></span>
                            </span>
                            <span class="text-[#262626] uppercase font-bold text-xs">{{ item.timestamp }}</span>
                        </div>
                        <div class="text-[#262626] leading-relaxed rich-text-content">
                            <div [innerHTML]="highlightContent(getContent(item))"></div>
                        </div>
                    </div>
                </div>

            </ng-container>
            <div #scrollBottom></div>
         </div>
      </div>

      <!-- Composer -->
      <div *ngIf="!conversation.isUserRemoved" class="border-t border-[#e6e6e6] p-4 bg-white">
         <div class="flex items-end gap-3">
            <div class="flex-1 border border-[#ccc] rounded-md overflow-hidden bg-white shadow-sm p-2">
                <div 
                    contentEditable 
                    class="w-full px-2 py-1 bg-white focus:outline-none min-h-[44px] max-h-[100px] overflow-auto"
                    data-placeholder="Type your message..."
                ></div>
            </div>
            <button class="w-11 h-11 rounded-full bg-[#007a91] hover:bg-[#006577] flex items-center justify-center transition-colors shrink-0">
               <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" class="text-white">
                  <path d="M22 2L11 13" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  <path d="M22 2L15 22L11 13L2 9L22 2Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
               </svg>
            </button>
         </div>
      </div>

    </div>
  `
})
export class ConversationDetailComponent implements OnChanges, AfterViewChecked {
    @Input() messageId: string | null = null;
    @Input() searchQuery: string = '';
    @Output() todoStatusChange = new EventEmitter<{ id: string, hasTodo: boolean }>();

    @ViewChild('scrollBottom') scrollBottom!: ElementRef;

    conversation: ConversationData | null = null;

    constructor(private messagesService: MessagesService) { }

    ngOnChanges(changes: SimpleChanges) {
        if (changes['messageId'] && this.messageId) {
            this.loadConversation(this.messageId);
        }
    }

    ngAfterViewChecked() {
    }

    loadConversation(id: string) {
        this.messagesService.getConversation(id).subscribe(data => {
            this.conversation = data;
        });
    }

    isSystem(item: ConversationItem): boolean {
        return isSystemMessage(item);
    }

    getSystemMessageText(item: any): string {
        switch (item.type) {
            case 'member_added': return `${item.actor} added ${item.targetUser}`;
            case 'member_removed': return `${item.actor} removed ${item.targetUser}`;
            case 'you_were_added': return `${item.actor} added You`;
            default: return 'System notification';
        }
    }

    // Helper to safely get properties from ConversationMessage
    getContent(item: ConversationItem): string {
        if (!isSystemMessage(item)) {
            return (item as any).content || '';
        }
        return '';
    }

    getSender(item: ConversationItem): string {
        if (!isSystemMessage(item)) {
            return (item as any).sender || '';
        }
        return '';
    }

    getIsOwn(item: ConversationItem): boolean {
        if (!isSystemMessage(item)) {
            return !!(item as any).isOwn;
        }
        return false;
    }

    highlight(text: string | undefined): string {
        return highlightText(text, this.searchQuery);
    }

    highlightContent(content: string): string {
        if (!this.searchQuery) return content;
        return highlightText(content, this.searchQuery);
    }
}
